//! Character-width helpers (UAX #11 East Asian Width plus zero-width classes).

#[path = "uwtables.rs"]
mod uwtables;

use uwtables::{WIDE, ZERO_WIDTH};

fn in_ranges(table: &[(u32, u32)], c: u32) -> bool {
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = table[mid];
        if c < a {
            hi = mid;
        } else if c > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

/// Display width of a single `char`. Control characters count as zero.
pub fn char_width(c: char) -> usize {
    let u = c as u32;
    if u < 0x20 || (0x7f..0xa0).contains(&u) {
        return 0;
    }
    if u < 0x7f {
        return 1;
    }
    if in_ranges(&ZERO_WIDTH, u) {
        return 0;
    }
    if in_ranges(&WIDE, u) {
        return 2;
    }
    1
}

/// Display width of a string.
pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

/// Truncate `s` so its display width does not exceed `max`, returning the
/// byte length of the prefix that fits.
pub fn truncate_bytes(s: &str, max: usize) -> usize {
    let mut w = 0;
    for (i, c) in s.char_indices() {
        let cw = char_width(c);
        if w + cw > max {
            return i;
        }
        w += cw;
    }
    s.len()
}

