//! Colors, modifiers and styles, mirroring the terminal model used by the app.

use std::fmt;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum Color {
    #[default]
    Reset,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    Gray,
    DarkGray,
    LightRed,
    LightGreen,
    LightYellow,
    LightBlue,
    LightMagenta,
    LightCyan,
    White,
    Rgb(u8, u8, u8),
    Indexed(u8),
}

impl Color {
    /// Parse the textual form accepted in the themes file.
    ///
    /// Accepts the terminal color names (case-insensitively), `#RRGGBB`, and a
    /// bare decimal number for an indexed color.
    pub fn parse(s: &str) -> Option<Color> {
        let t = s.trim();
        if let Some(hex) = t.strip_prefix('#') {
            if hex.len() == 6 {
                let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
                let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
                let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
                return Some(Color::Rgb(r, g, b));
            }
            return None;
        }
        let lower = t.to_ascii_lowercase();
        let c = match lower.as_str() {
            "reset" => Color::Reset,
            "black" => Color::Black,
            "red" => Color::Red,
            "green" => Color::Green,
            "yellow" => Color::Yellow,
            "blue" => Color::Blue,
            "magenta" => Color::Magenta,
            "cyan" => Color::Cyan,
            "gray" | "grey" => Color::Gray,
            "darkgray" | "darkgrey" => Color::DarkGray,
            "lightred" => Color::LightRed,
            "lightgreen" => Color::LightGreen,
            "lightyellow" => Color::LightYellow,
            "lightblue" => Color::LightBlue,
            "lightmagenta" => Color::LightMagenta,
            "lightcyan" => Color::LightCyan,
            "white" => Color::White,
            _ => {
                if let Ok(n) = lower.parse::<u8>() {
                    return Some(Color::Indexed(n));
                }
                return None;
            }
        };
        Some(c)
    }

    /// Canonical name used when serializing themes.
    pub fn to_toml_string(self) -> String {
        match self {
            Color::Reset => "Reset".into(),
            Color::Black => "Black".into(),
            Color::Red => "Red".into(),
            Color::Green => "Green".into(),
            Color::Yellow => "Yellow".into(),
            Color::Blue => "Blue".into(),
            Color::Magenta => "Magenta".into(),
            Color::Cyan => "Cyan".into(),
            Color::Gray => "Gray".into(),
            Color::DarkGray => "DarkGray".into(),
            Color::LightRed => "LightRed".into(),
            Color::LightGreen => "LightGreen".into(),
            Color::LightYellow => "LightYellow".into(),
            Color::LightBlue => "LightBlue".into(),
            Color::LightMagenta => "LightMagenta".into(),
            Color::LightCyan => "LightCyan".into(),
            Color::White => "White".into(),
            Color::Rgb(r, g, b) => format!("#{r:02X}{g:02X}{b:02X}"),
            Color::Indexed(n) => n.to_string(),
        }
    }

    /// SGR parameters selecting this color as foreground (`fg = true`) or
    /// background.
    fn sgr(self, fg: bool) -> String {
        let base = if fg { 30 } else { 40 };
        let bright = if fg { 90 } else { 100 };
        match self {
            Color::Reset => format!("{}", if fg { 39 } else { 49 }),
            Color::Black => format!("{}", base),
            Color::Red => format!("{}", base + 1),
            Color::Green => format!("{}", base + 2),
            Color::Yellow => format!("{}", base + 3),
            Color::Blue => format!("{}", base + 4),
            Color::Magenta => format!("{}", base + 5),
            Color::Cyan => format!("{}", base + 6),
            Color::Gray => format!("{}", base + 7),
            Color::DarkGray => format!("{}", bright),
            Color::LightRed => format!("{}", bright + 1),
            Color::LightGreen => format!("{}", bright + 2),
            Color::LightYellow => format!("{}", bright + 3),
            Color::LightBlue => format!("{}", bright + 4),
            Color::LightMagenta => format!("{}", bright + 5),
            Color::LightCyan => format!("{}", bright + 6),
            Color::White => format!("{}", bright + 7),
            Color::Rgb(r, g, b) => format!("{};2;{r};{g};{b}", if fg { 38 } else { 48 }),
            Color::Indexed(n) => format!("{};5;{n}", if fg { 38 } else { 48 }),
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Modifier(pub u16);

impl Modifier {
    pub const NONE: Modifier = Modifier(0);
    pub const BOLD: Modifier = Modifier(1 << 0);
    pub const DIM: Modifier = Modifier(1 << 1);
    pub const ITALIC: Modifier = Modifier(1 << 2);
    pub const UNDERLINED: Modifier = Modifier(1 << 3);
    pub const SLOW_BLINK: Modifier = Modifier(1 << 4);
    pub const RAPID_BLINK: Modifier = Modifier(1 << 5);
    pub const REVERSED: Modifier = Modifier(1 << 6);
    pub const HIDDEN: Modifier = Modifier(1 << 7);
    pub const CROSSED_OUT: Modifier = Modifier(1 << 8);

    /// Names in the order used when serializing, matching the bit order.
    const NAMES: [(Modifier, &'static str); 9] = [
        (Modifier::BOLD, "BOLD"),
        (Modifier::DIM, "DIM"),
        (Modifier::ITALIC, "ITALIC"),
        (Modifier::UNDERLINED, "UNDERLINED"),
        (Modifier::SLOW_BLINK, "SLOW_BLINK"),
        (Modifier::RAPID_BLINK, "RAPID_BLINK"),
        (Modifier::REVERSED, "REVERSED"),
        (Modifier::HIDDEN, "HIDDEN"),
        (Modifier::CROSSED_OUT, "CROSSED_OUT"),
    ];

    pub fn contains(self, other: Modifier) -> bool {
        self.0 & other.0 == other.0
    }

    pub fn is_empty(self) -> bool {
        self.0 == 0
    }

    pub fn insert(&mut self, other: Modifier) {
        self.0 |= other.0;
    }

    pub fn remove(&mut self, other: Modifier) {
        self.0 &= !other.0;
    }

    /// Parse the bitflags textual form, e.g. `"BOLD | ITALIC"`.
    pub fn parse(s: &str) -> Result<Modifier, String> {
        let mut m = Modifier::NONE;
        let trimmed = s.trim();
        if trimmed.is_empty() {
            return Ok(m);
        }
        for part in trimmed.split('|') {
            let p = part.trim();
            if p.is_empty() {
                return Err(format!("unrecognized named flag `{p}`"));
            }
            match Modifier::NAMES.iter().find(|(_, n)| *n == p) {
                Some((flag, _)) => m.insert(*flag),
                None => return Err(format!("unrecognized named flag `{p}`")),
            }
        }
        Ok(m)
    }
}

impl fmt::Display for Modifier {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut first = true;
        for (flag, name) in Modifier::NAMES {
            if self.contains(flag) {
                if !first {
                    f.write_str(" | ")?;
                }
                f.write_str(name)?;
                first = false;
            }
        }
        Ok(())
    }
}

impl std::ops::BitOr for Modifier {
    type Output = Modifier;
    fn bitor(self, rhs: Modifier) -> Modifier {
        Modifier(self.0 | rhs.0)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub underline_color: Option<Color>,
    pub add_modifier: Modifier,
    pub sub_modifier: Modifier,
}

impl Style {
    pub const fn new() -> Style {
        Style {
            fg: None,
            bg: None,
            underline_color: None,
            add_modifier: Modifier::NONE,
            sub_modifier: Modifier::NONE,
        }
    }

    pub const fn fg(mut self, c: Color) -> Style {
        self.fg = Some(c);
        self
    }

    pub const fn bg(mut self, c: Color) -> Style {
        self.bg = Some(c);
        self
    }

    pub const fn underline_color(mut self, c: Color) -> Style {
        self.underline_color = Some(c);
        self
    }

    pub fn add_modifier(mut self, m: Modifier) -> Style {
        self.sub_modifier.remove(m);
        self.add_modifier.insert(m);
        self
    }

    pub fn remove_modifier(mut self, m: Modifier) -> Style {
        self.add_modifier.remove(m);
        self.sub_modifier.insert(m);
        self
    }

    /// Combine with `other` taking precedence, as ratatui's `patch` does.
    pub fn patch(mut self, other: Style) -> Style {
        self.fg = other.fg.or(self.fg);
        self.bg = other.bg.or(self.bg);
        self.underline_color = other.underline_color.or(self.underline_color);
        self.add_modifier.remove(other.sub_modifier);
        self.add_modifier.insert(other.add_modifier);
        self.sub_modifier.remove(other.add_modifier);
        self.sub_modifier.insert(other.sub_modifier);
        self
    }
}

/// Style of a rendered cell after all patches have been resolved.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct CellStyle {
    pub fg: Color,
    pub bg: Color,
    pub underline_color: Color,
    pub modifier: Modifier,
}

impl Default for CellStyle {
    fn default() -> Self {
        CellStyle {
            fg: Color::Reset,
            bg: Color::Reset,
            underline_color: Color::Reset,
            modifier: Modifier::NONE,
        }
    }
}

impl CellStyle {
    pub fn apply(&mut self, s: Style) {
        if let Some(c) = s.fg {
            self.fg = c;
        }
        if let Some(c) = s.bg {
            self.bg = c;
        }
        if let Some(c) = s.underline_color {
            self.underline_color = c;
        }
        self.modifier.remove(s.sub_modifier);
        self.modifier.insert(s.add_modifier);
    }

    /// Emit the escape sequences that move the terminal from `prev` to `self`.
    pub fn diff_to(&self, prev: &CellStyle, out: &mut String) {
        // Removing a modifier requires a full reset first, mirroring how
        // crossterm's `SetAttribute` interacts with the mode flags.
        let removed = Modifier(prev.modifier.0 & !self.modifier.0);
        if !removed.is_empty() {
            out.push_str("\x1b[0m");
            let fresh = CellStyle::default();
            return Self::emit_full(self, &fresh, out);
        }
        Self::emit_full(self, prev, out);
    }

    fn emit_full(cur: &CellStyle, prev: &CellStyle, out: &mut String) {
        let added = Modifier(cur.modifier.0 & !prev.modifier.0);
        for (flag, code) in [
            (Modifier::BOLD, 1),
            (Modifier::DIM, 2),
            (Modifier::ITALIC, 3),
            (Modifier::UNDERLINED, 4),
            (Modifier::SLOW_BLINK, 5),
            (Modifier::RAPID_BLINK, 6),
            (Modifier::REVERSED, 7),
            (Modifier::HIDDEN, 8),
            (Modifier::CROSSED_OUT, 9),
        ] {
            if added.contains(flag) {
                out.push_str(&format!("\x1b[{code}m"));
            }
        }
        if cur.fg != prev.fg {
            out.push_str(&format!("\x1b[{}m", cur.fg.sgr(true)));
        }
        if cur.bg != prev.bg {
            out.push_str(&format!("\x1b[{}m", cur.bg.sgr(false)));
        }
        if cur.underline_color != prev.underline_color {
            match cur.underline_color {
                Color::Reset => out.push_str("\x1b[59m"),
                Color::Rgb(r, g, b) => out.push_str(&format!("\x1b[58;2;{r};{g};{b}m")),
                Color::Indexed(n) => out.push_str(&format!("\x1b[58;5;{n}m")),
                other => {
                    // Named colors are mapped onto their palette index.
                    let idx = named_index(other);
                    out.push_str(&format!("\x1b[58;5;{idx}m"));
                }
            }
        }
    }
}

fn named_index(c: Color) -> u8 {
    match c {
        Color::Black => 0,
        Color::Red => 1,
        Color::Green => 2,
        Color::Yellow => 3,
        Color::Blue => 4,
        Color::Magenta => 5,
        Color::Cyan => 6,
        Color::Gray => 7,
        Color::DarkGray => 8,
        Color::LightRed => 9,
        Color::LightGreen => 10,
        Color::LightYellow => 11,
        Color::LightBlue => 12,
        Color::LightMagenta => 13,
        Color::LightCyan => 14,
        Color::White => 15,
        Color::Indexed(n) => n,
        _ => 0,
    }
}

