    let total_f = total as f64;
    let mut base = vec![0f64; n];
    let mut weight = vec![0f64; n];
    for (i, c) in constraints.iter().enumerate() {
        match *c {
            Constraint::Length(v) => base[i] = v as f64,
            Constraint::Percentage(p) => base[i] = total_f * p as f64 / 100.0,
            Constraint::Ratio(a, b) => {
                base[i] = if b == 0 {
                    0.0
                } else {
                    total_f * a as f64 / b as f64
                }
            }
            Constraint::Min(v) => {
                base[i] = v as f64;
                weight[i] = 1.0;
            }
            Constraint::Max(v) => {
                base[i] = v as f64;
                weight[i] = 1.0;
            }
            Constraint::Fill(w) => {
                base[i] = 0.0;
                weight[i] = w.max(1) as f64;
            }
        }
    }

    let sum: f64 = base.iter().sum();
    let mut sizes = base.clone();
    if sum < total_f {
        let extra = total_f - sum;
        // `Max` may not grow past its bound, so it is excluded from sharing.
        let mut share: Vec<f64> = weight.clone();
        for (i, c) in constraints.iter().enumerate() {
            if matches!(c, Constraint::Max(_)) {
                share[i] = 0.0;
            }
        }
        let wsum: f64 = share.iter().sum();
        if wsum > 0.0 {
            for i in 0..n {
                sizes[i] += extra * share[i] / wsum;
            }
        } else {
            // Nothing is flexible: the trailing segment absorbs the slack.
            sizes[n - 1] += extra;
        }
    } else if sum > total_f {
        // Trim from the end until the total fits.
        let mut deficit = sum - total_f;
        for i in (0..n).rev() {
            if deficit <= 0.0 {
                break;
            }
            let take = deficit.min(sizes[i]);
            sizes[i] -= take;
            deficit -= take;
        }
    }

    let mut out = Vec::with_capacity(n);
    let mut acc = 0f64;
    let mut prev_edge = 0u16;
    for size in sizes {
        acc += size;
        let edge = round_half_up(acc).min(total as i64).max(prev_edge as i64) as u16;
        out.push(edge - prev_edge);
        prev_edge = edge;
    }
    if let Some(last) = out.last_mut() {
        *last += total - prev_edge;
    }
    out
}

fn round_half_up(v: f64) -> i64 {
    (v + 0.5).floor() as i64
}

/// Split `area` along `direction`.
pub fn split(area: Rect, direction: Direction, constraints: &[Constraint]) -> Vec<Rect> {
    let total = match direction {
        Direction::Horizontal => area.width,
        Direction::Vertical => area.height,
    };
    let sizes = solve(total, constraints);
    let mut out = Vec::with_capacity(sizes.len());
    let mut pos = match direction {
        Direction::Horizontal => area.x,
        Direction::Vertical => area.y,
    };
    for s in sizes {
        out.push(match direction {
            Direction::Horizontal => Rect::new(pos, area.y, s, area.height),
            Direction::Vertical => Rect::new(area.x, pos, area.width, s),
        });
        pos += s;
    }
    out
}

pub fn hsplit(area: Rect, constraints: &[Constraint]) -> Vec<Rect> {
    split(area, Direction::Horizontal, constraints)
}

pub fn vsplit(area: Rect, constraints: &[Constraint]) -> Vec<Rect> {
    split(area, Direction::Vertical, constraints)
}

/// Center a rect of the given percentage of `area` inside it.
pub fn centered_rect(percent_x: u16, percent_y: u16, area: Rect) -> Rect {
    let rows = vsplit(
        area,
        &[
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ],
    );
    let cols = hsplit(
        rows[1],
        &[
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ],
    );
    cols[1]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn percentage_split_rounds_half_up() {
        for (total, expected) in [(15u16, 5u16), (45, 14), (120, 36), (66, 20), (133, 40)] {
            let s = solve(total, &[Constraint::Percentage(30), Constraint::Percentage(70)]);
            assert_eq!(s[0], expected, "total={total}");
            assert_eq!(s[0] + s[1], total);
        }
    }

    #[test]
    fn min_absorbs_slack_and_length_is_trimmed_last() {
        assert_eq!(solve(7, &[Constraint::Min(2), Constraint::Length(1)]), [6, 1]);
        assert_eq!(solve(3, &[Constraint::Min(2), Constraint::Length(2)]), [2, 1]);
        assert_eq!(solve(2, &[Constraint::Min(2), Constraint::Length(2)]), [2, 0]);
        assert_eq!(solve(5, &[Constraint::Min(2), Constraint::Length(3)]), [2, 3]);
        assert_eq!(solve(6, &[Constraint::Min(2), Constraint::Length(3)]), [3, 3]);
    }
}

