//! A grid of styled cells plus the primitives widgets use to write into it.

use super::layout::Rect;
use super::style::{CellStyle, Style};
use super::unicode::char_width;

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Cell {
    /// The grapheme occupying this cell. Empty for the trailing half of a
    /// double-width character.
    pub symbol: String,
    pub style: CellStyle,
    /// True when this cell is the continuation of a wide character.
    pub skip: bool,
}

impl Default for Cell {
    fn default() -> Self {
        Cell {
            symbol: " ".to_string(),
            style: CellStyle::default(),
            skip: false,
        }
    }
}

impl Cell {
    pub fn reset(&mut self) {
        self.symbol.clear();
        self.symbol.push(' ');
        self.style = CellStyle::default();
        self.skip = false;
    }

    pub fn set_symbol(&mut self, s: &str) -> &mut Cell {
        self.symbol.clear();
        self.symbol.push_str(s);
        self
    }

    pub fn set_char(&mut self, c: char) -> &mut Cell {
        self.symbol.clear();
        self.symbol.push(c);
        self
    }

    pub fn set_style(&mut self, s: Style) -> &mut Cell {
        self.style.apply(s);
        self
    }
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Buffer {
    pub area: Rect,
    pub content: Vec<Cell>,
}

impl Buffer {
    pub fn empty(area: Rect) -> Buffer {
        Buffer {
            content: vec![Cell::default(); area.area() as usize],
            area,
        }
    }

    pub fn reset(&mut self) {
        for c in &mut self.content {
            c.reset();
        }
    }

    pub fn resize(&mut self, area: Rect) {
        self.content.resize(area.area() as usize, Cell::default());
        self.area = area;
        self.reset();
    }

    fn index_of(&self, x: u16, y: u16) -> Option<usize> {
        if x < self.area.x
            || x >= self.area.right()
            || y < self.area.y
            || y >= self.area.bottom()
        {
            return None;
        }
        Some(
            (y - self.area.y) as usize * self.area.width as usize + (x - self.area.x) as usize,
        )
    }

    pub fn get(&self, x: u16, y: u16) -> Option<&Cell> {
        self.index_of(x, y).map(|i| &self.content[i])
    }

    pub fn get_mut(&mut self, x: u16, y: u16) -> Option<&mut Cell> {
        self.index_of(x, y).map(|i| &mut self.content[i])
    }

    pub fn set_style(&mut self, area: Rect, style: Style) {
        let area = area.intersection(self.area);
        for y in area.top()..area.bottom() {
            for x in area.left()..area.right() {
                if let Some(c) = self.get_mut(x, y) {
                    c.set_style(style);
                }
            }
        }
    }

    /// Write `s` starting at (x, y), clipped to `max_width` display columns.
    /// Returns the x position just past the written text and the width used.
    pub fn set_stringn(
        &mut self,
        x: u16,
        y: u16,
        s: &str,
        max_width: usize,
        style: Style,
    ) -> (u16, u16) {
        let mut used = 0usize;
        let mut cx = x;
        for ch in s.chars() {
            if ch == '\n' || ch == '\r' {
                continue;
            }
            let w = char_width(ch);
            if w == 0 {
                // Combining marks attach to the previous cell.
                if cx > x {
                    if let Some(prev) = self.get_mut(cx - 1, y) {
                        prev.symbol.push(ch);
                    }
                }
                continue;
            }
            if used + w > max_width {
                break;
            }
            if cx >= self.area.right() {
                break;
            }
            match self.get_mut(cx, y) {
                Some(cell) => {
                    cell.set_char(ch);
                    cell.set_style(style);
                    cell.skip = false;
                }
                None => break,
            }
            for i in 1..w as u16 {
                if let Some(cell) = self.get_mut(cx + i, y) {
                    cell.symbol.clear();
                    cell.set_style(style);
                    cell.skip = true;
                }
            }
            cx += w as u16;
            used += w;
        }
        (cx, used as u16)
    }

    pub fn set_string(&mut self, x: u16, y: u16, s: &str, style: Style) {
        let max = self.area.right().saturating_sub(x) as usize;
        self.set_stringn(x, y, s, max, style);
    }

    /// Cells that differ from `other`, ready to be painted.
    pub fn diff<'a>(&self, other: &'a Buffer) -> Vec<(u16, u16, &'a Cell)> {
        let width = self.area.width as usize;
        let mut out = Vec::new();
        let mut to_skip = 0usize;
        for (i, (cur, prev)) in other.content.iter().zip(self.content.iter()).enumerate() {
            if (cur != prev || cur.skip != prev.skip) && to_skip == 0 {
                let x = self.area.x + (i % width) as u16;
                let y = self.area.y + (i / width) as u16;
                out.push((x, y, cur));
            }
            let w = cur.symbol.chars().next().map_or(1, char_width);
            to_skip = w.saturating_sub(1).max(to_skip.saturating_sub(1));
        }
        out
    }
}

