//! Raw-mode terminal control, ANSI rendering and key-event decoding.

use std::ffi::{c_int, c_ulong, c_void};
use std::io::{Read, Write};
use std::os::fd::AsRawFd;

use super::buffer::Buffer;
use super::layout::Rect;
use super::style::{CellStyle, Color, Modifier};

// ---------------------------------------------------------------------------
// libc bindings
// ---------------------------------------------------------------------------

const NCCS: usize = 32;

#[repr(C)]
#[derive(Clone, Copy)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; NCCS],
    c_ispeed: u32,
    c_ospeed: u32,
}

#[repr(C)]
#[derive(Default, Clone, Copy)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

#[repr(C)]
struct PollFd {
    fd: c_int,
    events: i16,
    revents: i16,
}

const POLLIN: i16 = 0x001;
const TCSANOW: c_int = 0;
const TIOCGWINSZ: c_ulong = 0x5413;

// Input flags
const IGNBRK: u32 = 0o1;
const BRKINT: u32 = 0o2;
const PARMRK: u32 = 0o10;
const ISTRIP: u32 = 0o40;
const INLCR: u32 = 0o100;
const IGNCR: u32 = 0o200;
const ICRNL: u32 = 0o400;
const IXON: u32 = 0o2000;
// Output flags
const OPOST: u32 = 0o1;
// Local flags
const ECHO: u32 = 0o10;
const ECHONL: u32 = 0o100;
const ICANON: u32 = 0o2;
const ISIG: u32 = 0o1;
const IEXTEN: u32 = 0o100000;
// Control flags
const CSIZE: u32 = 0o60;
const PARENB: u32 = 0o400;
const CS8: u32 = 0o60;

unsafe extern "C" {
    fn tcgetattr(fd: c_int, termios_p: *mut Termios) -> c_int;
    fn tcsetattr(fd: c_int, optional_actions: c_int, termios_p: *const Termios) -> c_int;
    fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
    fn poll(fds: *mut PollFd, nfds: c_ulong, timeout: c_int) -> c_int;
    fn isatty(fd: c_int) -> c_int;
    fn signal(sig: c_int, handler: usize) -> usize;
}

/// Terminal size in (columns, rows).
pub fn terminal_size() -> std::io::Result<(u16, u16)> {
    let mut ws = Winsize::default();
    let rc = unsafe { ioctl(std::io::stdout().as_raw_fd(), TIOCGWINSZ, &mut ws as *mut Winsize) };
    if rc != 0 || ws.ws_col == 0 {
        return Err(std::io::Error::last_os_error());
    }
    Ok((ws.ws_col, ws.ws_row))
}

pub fn is_tty() -> bool {
    unsafe { isatty(std::io::stdin().as_raw_fd()) == 1 }
}

pub struct RawMode {
    original: Termios,
    fd: c_int,
}

impl RawMode {
    pub fn enable() -> std::io::Result<RawMode> {
        let fd = std::io::stdin().as_raw_fd();
        let mut t = unsafe { std::mem::zeroed::<Termios>() };
        if unsafe { tcgetattr(fd, &mut t) } != 0 {
            return Err(std::io::Error::last_os_error());
        }
        let original = t;
        // cfmakeraw
        t.c_iflag &= !(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
        t.c_oflag &= !OPOST;
        t.c_lflag &= !(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
        t.c_cflag &= !(CSIZE | PARENB);
        t.c_cflag |= CS8;
        t.c_cc[6] = 1; // VMIN
        t.c_cc[5] = 0; // VTIME
        if unsafe { tcsetattr(fd, TCSANOW, &t) } != 0 {
            return Err(std::io::Error::last_os_error());
        }
        Ok(RawMode { original, fd })
    }

    pub fn disable(&self) {
        unsafe {
            tcsetattr(self.fd, TCSANOW, &self.original);
        }
    }
}

// ---------------------------------------------------------------------------
// Events
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct KeyModifiers(pub u8);

impl KeyModifiers {
    pub const NONE: KeyModifiers = KeyModifiers(0);
    pub const SHIFT: KeyModifiers = KeyModifiers(1);
    pub const ALT: KeyModifiers = KeyModifiers(2);
    pub const CONTROL: KeyModifiers = KeyModifiers(4);

    pub fn contains(self, o: KeyModifiers) -> bool {
        self.0 & o.0 == o.0
    }

    pub fn is_empty(self) -> bool {
        self.0 == 0
    }
}

impl std::ops::BitOr for KeyModifiers {
    type Output = KeyModifiers;
    fn bitor(self, r: KeyModifiers) -> KeyModifiers {
        KeyModifiers(self.0 | r.0)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum KeyCode {
    Char(char),
    Enter,
    Tab,
    BackTab,
    Backspace,
    Esc,
    Left,
    Right,
    Up,
    Down,
    Home,
    End,
    PageUp,
    PageDown,
    Delete,
    Insert,
    F(u8),
    Null,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct KeyEvent {
    pub code: KeyCode,
    pub modifiers: KeyModifiers,
}

impl KeyEvent {
    pub fn new(code: KeyCode, modifiers: KeyModifiers) -> KeyEvent {
        KeyEvent { code, modifiers }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Event {
    Key(KeyEvent),
    Resize(u16, u16),
}

/// Buffered stdin reader that decodes ANSI input into key events.
pub struct EventReader {
    pending: Vec<u8>,
    last_size: (u16, u16),
}

impl EventReader {
    pub fn new(size: (u16, u16)) -> EventReader {
        EventReader {
            pending: Vec::new(),
            last_size: size,
        }
    }

    fn fill(&mut self, timeout_ms: c_int) -> std::io::Result<bool> {
        let fd = std::io::stdin().as_raw_fd();
        let mut pfd = PollFd {
            fd,
            events: POLLIN,
            revents: 0,
        };
        let rc = unsafe { poll(&mut pfd, 1, timeout_ms) };
        if rc <= 0 {
            return Ok(false);
        }
        let mut buf = [0u8; 4096];
        let n = std::io::stdin().read(&mut buf)?;
        if n == 0 {
            return Ok(false);
        }
        self.pending.extend_from_slice(&buf[..n]);
        Ok(true)
    }

    /// Block until an event is available.
    pub fn read(&mut self) -> std::io::Result<Event> {
        loop {
            if let Some(ev) = self.parse() {
                return Ok(ev);
            }
            // Poll with a timeout so window resizes are still noticed.
            if !self.fill(100)? {
                if let Ok(sz) = terminal_size() {
                    if sz != self.last_size {
                        self.last_size = sz;
                        return Ok(Event::Resize(sz.0, sz.1));
                    }
                }
                if resize_pending() {
                    if let Ok(sz) = terminal_size() {
                        self.last_size = sz;
                        return Ok(Event::Resize(sz.0, sz.1));
                    }
                }
            }
        }
    }

    fn parse(&mut self) -> Option<Event> {
        if self.pending.is_empty() {
            return None;
        }
        let (ev, used) = decode(&self.pending)?;
        self.pending.drain(..used);
        Some(ev)
    }
}

static mut RESIZED: bool = false;

extern "C" fn on_sigwinch(_: c_int) {
    unsafe {
        RESIZED = true;
    }
}

fn resize_pending() -> bool {
    unsafe {
        let r = RESIZED;
        RESIZED = false;
        r
    }
}

pub fn install_resize_handler() {
    const SIGWINCH: c_int = 28;
    unsafe {
        signal(SIGWINCH, on_sigwinch as usize);
    }
}

/// Decode one event from the front of `b`; returns the event and bytes used.
fn decode(b: &[u8]) -> Option<(Event, usize)> {
    let c0 = b[0];
    if c0 == 0x1b {
        if b.len() == 1 {
            return Some((key(KeyCode::Esc, KeyModifiers::NONE), 1));
        }
        match b[1] {
            b'[' => return decode_csi(b),
            b'O' => {
                if b.len() < 3 {
                    return Some((key(KeyCode::Esc, KeyModifiers::NONE), 1));
                }
                let code = match b[2] {
                    b'A' => KeyCode::Up,
                    b'B' => KeyCode::Down,
                    b'C' => KeyCode::Right,
                    b'D' => KeyCode::Left,
                    b'H' => KeyCode::Home,
                    b'F' => KeyCode::End,
                    b'P' => KeyCode::F(1),
                    b'Q' => KeyCode::F(2),
                    b'R' => KeyCode::F(3),
                    b'S' => KeyCode::F(4),
                    _ => return Some((key(KeyCode::Esc, KeyModifiers::NONE), 1)),
                };
                return Some((key(code, KeyModifiers::NONE), 3));
            }
            0x1b => return Some((key(KeyCode::Esc, KeyModifiers::NONE), 1)),
            _ => {
                // Alt + key
                let (ev, used) = decode(&b[1..])?;
                if let Event::Key(k) = ev {
                    return Some((
                        key(k.code, k.modifiers | KeyModifiers::ALT),
                        used + 1,
                    ));
                }
                return None;
            }
        }
    }
    // Control characters
    match c0 {
        b'\r' | b'\n' => return Some((key(KeyCode::Enter, KeyModifiers::NONE), 1)),
        b'\t' => return Some((key(KeyCode::Tab, KeyModifiers::NONE), 1)),
        0x7f => return Some((key(KeyCode::Backspace, KeyModifiers::NONE), 1)),
        0x00 => {
            return Some((
                key(KeyCode::Char(' '), KeyModifiers::CONTROL),
                1,
            ))
        }
        0x01..=0x1a => {
            let ch = (c0 - 1 + b'a') as char;
            return Some((key(KeyCode::Char(ch), KeyModifiers::CONTROL), 1));
        }
        0x1c..=0x1f => {
            let ch = (c0 - 0x1c + b'4') as char;
            return Some((key(KeyCode::Char(ch), KeyModifiers::CONTROL), 1));
        }
        _ => {}
    }
    // UTF-8 character
    let len = utf8_len(c0);
    if b.len() < len {
        return None;
    }
    let s = std::str::from_utf8(&b[..len]).ok()?;
    let ch = s.chars().next()?;
    Some((key(KeyCode::Char(ch), KeyModifiers::NONE), len))
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if b >> 5 == 0b110 {
        2
    } else if b >> 4 == 0b1110 {
        3
    } else if b >> 3 == 0b11110 {
        4
    } else {
        1
    }
}

fn key(code: KeyCode, modifiers: KeyModifiers) -> Event {
    Event::Key(KeyEvent { code, modifiers })
}

fn decode_csi(b: &[u8]) -> Option<(Event, usize)> {
    // Find the final byte of the sequence.
    let mut i = 2;
    while i < b.len() && !(0x40..=0x7e).contains(&b[i]) {
        i += 1;
    }
    if i >= b.len() {
        return None;
    }
    let final_byte = b[i];
    let params = std::str::from_utf8(&b[2..i]).ok()?;
    let used = i + 1;
    let nums: Vec<u32> = params
        .split(';')
        .map(|p| p.parse::<u32>().unwrap_or(0))
        .collect();
    let modifiers = nums
        .get(1)
        .copied()
        .filter(|m| *m > 0)
        .map(decode_modifier)
        .unwrap_or(KeyModifiers::NONE);

    let code = match final_byte {
        b'A' => KeyCode::Up,
        b'B' => KeyCode::Down,
        b'C' => KeyCode::Right,
        b'D' => KeyCode::Left,
        b'H' => KeyCode::Home,
        b'F' => KeyCode::End,
        b'Z' => return Some((key(KeyCode::BackTab, KeyModifiers::SHIFT), used)),
        b'~' => match nums.first().copied().unwrap_or(0) {
            1 | 7 => KeyCode::Home,
            2 => KeyCode::Insert,
            3 => KeyCode::Delete,
            4 | 8 => KeyCode::End,
            5 => KeyCode::PageUp,
            6 => KeyCode::PageDown,
            n @ 11..=15 => KeyCode::F(n as u8 - 10),
            n @ 17..=21 => KeyCode::F(n as u8 - 11),
            n @ 23..=26 => KeyCode::F(n as u8 - 12),
            _ => return Some((key(KeyCode::Null, KeyModifiers::NONE), used)),
        },
        _ => return Some((key(KeyCode::Null, KeyModifiers::NONE), used)),
    };
    Some((key(code, modifiers), used))
}

fn decode_modifier(m: u32) -> KeyModifiers {
    let bits = m.saturating_sub(1);
    let mut out = KeyModifiers::NONE;
    if bits & 1 != 0 {
        out = out | KeyModifiers::SHIFT;
    }
    if bits & 2 != 0 {
        out = out | KeyModifiers::ALT;
    }
    if bits & 4 != 0 {
        out = out | KeyModifiers::CONTROL;
    }
    out
}

