/// True when the `NO_COLOR` environment variable is set to a non-empty value.
pub fn color_disabled() -> bool {
    !std::env::var("NO_COLOR").unwrap_or_default().is_empty()
}

fn color_sgr(c: Color, fg: bool, out: &mut String) {
    if color_disabled() {
        return;
    }
    let (basic, extended) = if fg { (39, 38) } else { (49, 48) };
    match c {
        Color::Reset => out.push_str(&basic.to_string()),
        Color::Rgb(r, g, b) => out.push_str(&format!("{extended};2;{r};{g};{b}")),
        Color::Indexed(n) => out.push_str(&format!("{extended};5;{n}")),
        named => {
            let idx = match named {
                Color::Black => 0,
                Color::Red => 1,
                Color::Green => 2,
                Color::Yellow => 3,
                Color::Blue => 4,
                Color::Magenta => 5,
                Color::Cyan => 6,
                Color::Gray => 7,
                Color::DarkGray => 8,
                Color::LightRed => 9,
                Color::LightGreen => 10,
                Color::LightYellow => 11,
                Color::LightBlue => 12,
                Color::LightMagenta => 13,
                Color::LightCyan => 14,
                Color::White => 15,
                _ => 0,
            };
            out.push_str(&format!("{extended};5;{idx}"));
        }
    }
}

/// Emit the SGR sequence that transitions the modifier set from `from` to `to`.
fn modifier_diff(from: Modifier, to: Modifier, out: &mut String) {
    let removed = Modifier(from.0 & !to.0);
    if removed.contains(Modifier::REVERSED) {
        out.push_str("\x1b[27m");
    }
    if removed.contains(Modifier::BOLD) {
        out.push_str("\x1b[22m");
        if to.contains(Modifier::DIM) {
            out.push_str("\x1b[2m");
        }
    }
    if removed.contains(Modifier::ITALIC) {
        out.push_str("\x1b[23m");
    }
    if removed.contains(Modifier::UNDERLINED) {
        out.push_str("\x1b[24m");
    }
    if removed.contains(Modifier::DIM) {
        out.push_str("\x1b[22m");
    }
    if removed.contains(Modifier::CROSSED_OUT) {
        out.push_str("\x1b[29m");
    }
    if removed.contains(Modifier::SLOW_BLINK) || removed.contains(Modifier::RAPID_BLINK) {
        out.push_str("\x1b[25m");
    }
    if removed.contains(Modifier::HIDDEN) {
        out.push_str("\x1b[28m");
    }

    let added = Modifier(to.0 & !from.0);
    if added.contains(Modifier::REVERSED) {
        out.push_str("\x1b[7m");
    }
    if added.contains(Modifier::BOLD) {
        out.push_str("\x1b[1m");
    }
    if added.contains(Modifier::ITALIC) {
        out.push_str("\x1b[3m");
    }
    if added.contains(Modifier::UNDERLINED) {
        out.push_str("\x1b[4m");
    }
    if added.contains(Modifier::DIM) {
        out.push_str("\x1b[2m");
    }
    if added.contains(Modifier::CROSSED_OUT) {
        out.push_str("\x1b[9m");
    }
    if added.contains(Modifier::SLOW_BLINK) {
        out.push_str("\x1b[5m");
    }
    if added.contains(Modifier::RAPID_BLINK) {
        out.push_str("\x1b[6m");
    }
    if added.contains(Modifier::HIDDEN) {
        out.push_str("\x1b[8m");
    }
}

/// Double-buffered terminal renderer.
pub struct Terminal {
    buffers: [Buffer; 2],
    current: usize,
    pub size: Rect,
    cursor_hidden: bool,
    out: std::io::BufWriter<std::io::Stdout>,
}

impl Terminal {
    pub fn new() -> std::io::Result<Terminal> {
        let (w, h) = terminal_size()?;
        let area = Rect::new(0, 0, w, h);
        Ok(Terminal {
            buffers: [Buffer::empty(area), Buffer::empty(area)],
            current: 0,
            size: area,
            cursor_hidden: false,
            out: std::io::BufWriter::new(std::io::stdout()),
        })
    }

    pub fn enter(&mut self) -> std::io::Result<()> {
        self.out.write_all(b"\x1b[?1049h")?;
        self.out.flush()
    }

    pub fn leave(&mut self) -> std::io::Result<()> {
        self.out.write_all(b"\x1b[?1049l\x1b[?25h")?;
        self.out.flush()
    }

    pub fn resize(&mut self, w: u16, h: u16) {
        let area = Rect::new(0, 0, w, h);
        self.buffers[0].resize(area);
        self.buffers[1].resize(area);
        self.size = area;
        // Force a full repaint on the next draw.
        self.buffers[1 - self.current].reset();
    }

    /// Repaint from scratch, e.g. after a resize.
    pub fn clear(&mut self) -> std::io::Result<()> {
        self.out.write_all(b"\x1b[2J")?;
        self.buffers[1 - self.current].reset();
        Ok(())
    }

    pub fn buffer_mut(&mut self) -> &mut Buffer {
        &mut self.buffers[self.current]
    }

    /// Flush the pending buffer to the terminal and swap.
    pub fn flush(&mut self, cursor: Option<(u16, u16)>) -> std::io::Result<()> {
        let prev = &self.buffers[1 - self.current];
        let next = &self.buffers[self.current];
        let updates = prev.diff(next);

        let mut s = String::new();
        let mut style = CellStyle::default();
        let mut last: Option<(u16, u16)> = None;
        for (x, y, cell) in updates {
            if last != Some((x, y)) {
                s.push_str(&format!("\x1b[{};{}H", y + 1, x + 1));
            }
            if cell.style.modifier != style.modifier {
                modifier_diff(style.modifier, cell.style.modifier, &mut s);
                style.modifier = cell.style.modifier;
            }
            if cell.style.fg != style.fg || cell.style.bg != style.bg {
                s.push_str("\x1b[");
                color_sgr(cell.style.fg, true, &mut s);
                s.push(';');
                color_sgr(cell.style.bg, false, &mut s);
                s.push('m');
                style.fg = cell.style.fg;
                style.bg = cell.style.bg;
            }
            if cell.style.underline_color != style.underline_color {
                s.push_str("\x1b[");
                match cell.style.underline_color {
                    Color::Reset => s.push_str("59"),
                    other => {
                        if !color_disabled() {
                            let mut tmp = String::new();
                            color_sgr(other, true, &mut tmp);
                            // 38;... -> 58;...
                            s.push_str(&tmp.replacen("38", "58", 1));
                        }
                    }
                }
                s.push('m');
                style.underline_color = cell.style.underline_color;
            }
            if cell.skip {
                last = Some((x + 1, y));
                continue;
            }
            s.push_str(&cell.symbol);
            let w = super::unicode::str_width(&cell.symbol).max(1) as u16;
            last = Some((x + w, y));
        }

        s.push_str("\x1b[");
        color_sgr(Color::Reset, true, &mut s);
        s.push_str("m\x1b[");
        color_sgr(Color::Reset, false, &mut s);
        s.push_str("m\x1b[59m\x1b[0m");

        match cursor {
            None => {
                if !self.cursor_hidden {
                    s.push_str("\x1b[?25l");
                    self.cursor_hidden = true;
                }
            }
            Some((cx, cy)) => {
                s.push_str(&format!("\x1b[{};{}H", cy + 1, cx + 1));
                if self.cursor_hidden {
                    s.push_str("\x1b[?25h");
                    self.cursor_hidden = false;
                }
            }
        }

        self.out.write_all(s.as_bytes())?;
        self.out.flush()?;

        self.current = 1 - self.current;
        self.buffers[self.current].reset();
        Ok(())
    }
}
